/// <summary>
/// PricingAttribute of table <c>InventTable</c> field standardPalletQuantity.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableStandardPalletQuantity extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, standardPalletQuantity);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Real);
    InventTable inventTable;

    while select inventTable
        group by standardPalletQuantity
    {
        if (! ret.in(inventTable.standardPalletQuantity))
        {
            ret.add(inventTable.standardPalletQuantity);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, standardPalletQuantity));
    qbr.value(queryValue(_value));
}
